<?php
declare(strict_types=1);

require_once __DIR__ . '/group_keys.php';

/**
 * Server-side cache for audio generated by the browser-based vits-web model.
 * Audio files are never exposed directly; authenticated endpoints stream them.
 */

function tts_audio_normalize_language(string $language): string {
  $language = strtolower(trim($language));
  return $language === 'en' ? 'en' : 'de';
}

function tts_audio_voice_for_language(string $language): string {
  $language = tts_audio_normalize_language($language);
  $cfg = app_config();
  $student = is_array($cfg['student'] ?? null) ? $cfg['student'] : [];
  if ($language === 'en') {
    $voice = trim((string)($student['tts_voice_en'] ?? ''));
    return $voice !== '' ? $voice : 'en_US-lessac-medium';
  }
  $voice = trim((string)($student['tts_voice_de'] ?? ($student['tts_voice'] ?? '')));
  return $voice !== '' ? $voice : 'de_DE-thorsten-medium';
}

function tts_audio_normalize_text(string $text): string {
  $text = preg_replace('/[\p{Z}\s]+/u', ' ', $text) ?? $text;
  return trim($text);
}

function tts_audio_cache_key(string $text, string $language, string $voiceId): string {
  $language = tts_audio_normalize_language($language);
  $normalized = tts_audio_normalize_text($text);
  return hash('sha256', trim($voiceId) . "\n" . $language . "\n" . $normalized);
}

function tts_audio_uploads_relative_dir(): string {
  $cfg = app_config();
  $uploads = trim((string)($cfg['app']['uploads_dir'] ?? 'uploads'), '/\\');
  if ($uploads === '' || str_contains($uploads, '..')) $uploads = 'uploads';
  return $uploads . '/tts-audio';
}

function tts_audio_storage_root(bool $create = false): string {
  $path = dirname(__DIR__) . '/' . tts_audio_uploads_relative_dir();
  if ($create && !is_dir($path) && !@mkdir($path, 0750, true) && !is_dir($path)) {
    throw new RuntimeException(t('tts_audio.error.storage', 'Der Audio-Speicher konnte nicht angelegt werden.'));
  }
  if ($create && is_dir($path)) {
    $denyRules = "Require all denied\nDeny from all\n";
    if (!is_file($path . '/.htaccess')) @file_put_contents($path . '/.htaccess', $denyRules, LOCK_EX);
    if (!is_file($path . '/index.html')) @file_put_contents($path . '/index.html', '', LOCK_EX);
  }
  return $path;
}

function tts_audio_absolute_path(string $relativePath): ?string {
  $relativePath = str_replace('\\', '/', trim($relativePath));
  $allowedPrefix = tts_audio_uploads_relative_dir() . '/';
  if ($relativePath === '' || !str_starts_with($relativePath, $allowedPrefix) || str_contains($relativePath, '..')) return null;
  return dirname(__DIR__) . '/' . $relativePath;
}

function tts_audio_mime_extension(string $mimeType): ?string {
  $mimeType = strtolower(trim(explode(';', $mimeType, 2)[0]));
  $map = [
    'audio/wav' => 'wav',
    'audio/x-wav' => 'wav',
    'audio/wave' => 'wav',
    'audio/webm' => 'webm',
    'audio/ogg' => 'ogg',
    'audio/mpeg' => 'mp3',
    'application/octet-stream' => 'wav',
  ];
  return $map[$mimeType] ?? null;
}

function tts_audio_find(PDO $pdo, string $cacheKey): ?array {
  if (!preg_match('/^[a-f0-9]{64}$/', $cacheKey)) return null;
  $st = $pdo->prepare('SELECT * FROM tts_audio_files WHERE cache_key=? LIMIT 1');
  $st->execute([$cacheKey]);
  $row = $st->fetch(PDO::FETCH_ASSOC);
  if (!$row) return null;
  $path = tts_audio_absolute_path((string)($row['storage_path'] ?? ''));
  if ($path === null || !is_file($path)) return null;
  $row['_absolute_path'] = $path;
  return $row;
}

function tts_audio_link_to_class(
  PDO $pdo,
  int $classId,
  int $audioId,
  string $sourceType = 'runtime',
  string $sourceKey = '',
  string $sourceLabel = ''
): array {
  if ($classId <= 0 || $audioId <= 0) return [];
  $sourceType = preg_replace('/[^a-z0-9_-]/i', '', $sourceType) ?: 'runtime';
  $sourceKey = substr(trim($sourceKey), 0, 190);
  $sourceLabel = substr(trim($sourceLabel), 0, 255);
  $replacedAudioIds = [];
  if ($sourceKey !== '') {
    $old = $pdo->prepare(
      'SELECT audio_id
       FROM tts_audio_class_links
       WHERE class_id=? AND source_type=? AND source_key=? AND audio_id<>?'
    );
    $old->execute([$classId, $sourceType, $sourceKey, $audioId]);
    $replacedAudioIds = array_map('intval', $old->fetchAll(PDO::FETCH_COLUMN));
    if ($replacedAudioIds) {
      $deleteOld = $pdo->prepare(
        'DELETE FROM tts_audio_class_links
         WHERE class_id=? AND source_type=? AND source_key=? AND audio_id<>?'
      );
      $deleteOld->execute([$classId, $sourceType, $sourceKey, $audioId]);
    }
  }
  $st = $pdo->prepare(
    "INSERT INTO tts_audio_class_links (class_id, audio_id, source_type, source_key, source_label)
     VALUES (?, ?, ?, ?, ?)
     ON DUPLICATE KEY UPDATE
       source_key=IF(source_type IN ('competency','section','intro'), source_key,
         IF(VALUES(source_key)<>'', VALUES(source_key), source_key)),
       source_label=IF(source_type IN ('competency','section','intro'), source_label,
         IF(VALUES(source_label)<>'', VALUES(source_label), source_label)),
       source_type=IF(source_type IN ('competency','section','intro'), source_type, VALUES(source_type))"
  );
  $st->execute([$classId, $audioId, $sourceType, $sourceKey, $sourceLabel]);
  if ($replacedAudioIds && !$pdo->inTransaction()) tts_audio_remove_orphan_files($pdo, $replacedAudioIds);
  return $replacedAudioIds;
}

function tts_audio_store_upload(PDO $pdo, int $classId, array $upload, array $meta, bool $allowDisabledClass = false): array {
  if ($classId <= 0) throw new RuntimeException(t('tts_audio.error.class', 'Ungültige Klasse.'));
  $classSt = $pdo->prepare('SELECT id, tts_enabled FROM classes WHERE id=? LIMIT 1');
  $classSt->execute([$classId]);
  $class = $classSt->fetch(PDO::FETCH_ASSOC);
  if (!$class || (!$allowDisabledClass && (int)($class['tts_enabled'] ?? 0) !== 1)) {
    throw new RuntimeException(t('tts_audio.error.disabled', 'Vorlesen ist für diese Klasse nicht aktiviert.'));
  }

  $text = tts_audio_normalize_text((string)($meta['text'] ?? ''));
  $language = tts_audio_normalize_language((string)($meta['language'] ?? 'de'));
  $voiceId = trim((string)($meta['voice_id'] ?? ''));
  if ($voiceId === '') $voiceId = tts_audio_voice_for_language($language);
  if ($text === '' || strlen($text) > 12000) throw new RuntimeException(t('tts_audio.error.text', 'Ungültiger Vorlesetext.'));

  $cacheKey = tts_audio_cache_key($text, $language, $voiceId);
  $providedKey = strtolower(trim((string)($meta['cache_key'] ?? '')));
  if ($providedKey !== '' && !hash_equals($cacheKey, $providedKey)) {
    throw new RuntimeException(t('tts_audio.error.key', 'Der Audio-Schlüssel stimmt nicht mit dem Text überein.'));
  }

  $existing = tts_audio_find($pdo, $cacheKey);
  if ($existing) {
    tts_audio_link_to_class(
      $pdo,
      $classId,
      (int)$existing['id'],
      (string)($meta['source_type'] ?? 'runtime'),
      (string)($meta['source_key'] ?? ''),
      (string)($meta['source_label'] ?? '')
    );
    return $existing + ['cache_key' => $cacheKey, 'reused' => true];
  }

  $error = (int)($upload['error'] ?? UPLOAD_ERR_NO_FILE);
  $tmpName = (string)($upload['tmp_name'] ?? '');
  $size = (int)($upload['size'] ?? 0);
  if ($error !== UPLOAD_ERR_OK || $tmpName === '' || !is_uploaded_file($tmpName)) {
    throw new RuntimeException(t('tts_audio.error.upload', 'Die erzeugte Audiodatei konnte nicht übernommen werden.'));
  }
  if ($size <= 44 || $size > 12 * 1024 * 1024) {
    throw new RuntimeException(t('tts_audio.error.size', 'Die Audiodatei hat eine ungültige Größe.'));
  }

  $mime = trim((string)($upload['type'] ?? ''));
  if (function_exists('finfo_open')) {
    $finfo = finfo_open(FILEINFO_MIME_TYPE);
    if ($finfo) {
      $detected = finfo_file($finfo, $tmpName);
      finfo_close($finfo);
      if (is_string($detected) && $detected !== '') $mime = $detected;
    }
  }
  $extension = tts_audio_mime_extension($mime);
  if ($extension === null) throw new RuntimeException(t('tts_audio.error.type', 'Das Audioformat wird nicht unterstützt.'));

  $root = tts_audio_storage_root(true);
  $bucket = substr($cacheKey, 0, 2);
  $bucketAbs = $root . '/' . $bucket;
  if (!is_dir($bucketAbs) && !@mkdir($bucketAbs, 0750, true) && !is_dir($bucketAbs)) {
    throw new RuntimeException(t('tts_audio.error.storage', 'Der Audio-Speicher konnte nicht angelegt werden.'));
  }
  $filename = $cacheKey . '.' . $extension;
  $absolutePath = $bucketAbs . '/' . $filename;
  $relativePath = tts_audio_uploads_relative_dir() . '/' . $bucket . '/' . $filename;
  if (!move_uploaded_file($tmpName, $absolutePath)) {
    throw new RuntimeException(t('tts_audio.error.upload', 'Die erzeugte Audiodatei konnte nicht gespeichert werden.'));
  }
  @chmod($absolutePath, 0640);

  try {
    $pdo->beginTransaction();
    $st = $pdo->prepare(
      "INSERT INTO tts_audio_files
        (cache_key, language, voice_id, text_content, storage_path, mime_type, file_size)
       VALUES (?, ?, ?, ?, ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         id=LAST_INSERT_ID(id),
         language=VALUES(language),
         voice_id=VALUES(voice_id),
         text_content=VALUES(text_content),
         storage_path=VALUES(storage_path),
         mime_type=VALUES(mime_type),
         file_size=VALUES(file_size)"
    );
    $st->execute([$cacheKey, $language, $voiceId, $text, $relativePath, $mime, $size]);
    $audioId = (int)$pdo->lastInsertId();
    if ($audioId <= 0) {
      $existingId = $pdo->prepare('SELECT id FROM tts_audio_files WHERE cache_key=? LIMIT 1');
      $existingId->execute([$cacheKey]);
      $audioId = (int)($existingId->fetchColumn() ?: 0);
    }
    if ($audioId <= 0) throw new RuntimeException('Audio-ID fehlt.');
    $replacedAudioIds = tts_audio_link_to_class(
      $pdo,
      $classId,
      $audioId,
      (string)($meta['source_type'] ?? 'runtime'),
      (string)($meta['source_key'] ?? ''),
      (string)($meta['source_label'] ?? '')
    );
    $pdo->commit();
    if ($replacedAudioIds) tts_audio_remove_orphan_files($pdo, $replacedAudioIds);
  } catch (Throwable $e) {
    if ($pdo->inTransaction()) $pdo->rollBack();
    @unlink($absolutePath);
    throw $e;
  }

  $stored = tts_audio_find($pdo, $cacheKey);
  if (!$stored) throw new RuntimeException(t('tts_audio.error.upload', 'Die erzeugte Audiodatei konnte nicht gespeichert werden.'));
  return $stored + ['cache_key' => $cacheKey, 'reused' => false];
}

function tts_audio_translation(string $language, string $key, string $fallback): string {
  $catalog = translations_catalog();
  $bucket = $catalog[tts_audio_normalize_language($language)] ?? [];
  return array_key_exists($key, $bucket) ? (string)$bucket[$key] : $fallback;
}

function tts_audio_intro_text(string $html, array $class, array $student): string {
  $cfg = app_config();
  $brand = is_array($cfg['app']['brand'] ?? null) ? $cfg['app']['brand'] : [];
  $first = (string)($student['first_name'] ?? '');
  $last = (string)($student['last_name'] ?? '');
  $name = trim($first . ' ' . $last);
  $grade = $class['grade_level'] !== null ? (int)$class['grade_level'] : null;
  $label = trim((string)($class['label'] ?? ''));
  $className = ($grade !== null && $label !== '') ? ($grade . $label) : (string)($class['name'] ?? '');
  $escape = static fn(string $value): string => htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
  $replace = [
    '{{org_name}}' => $escape((string)($brand['org_name'] ?? 'LEB Tool')),
    '{{student_name}}' => $escape($name !== '' ? $name : $first),
    '{{first_name}}' => $escape($first),
    '{{last_name}}' => $escape($last),
    '{{class}}' => $escape($className),
    '{{school_year}}' => $escape((string)($class['school_year'] ?? '')),
  ];
  $html = preg_replace('~<script\b[^>]*>.*?</script>~is', '', $html) ?? $html;
  $html = strtr($html, $replace);
  $html = preg_replace('~<(?:br\s*/?|/?(?:p|div|h[1-6]|li|ul|ol|section|article))\b[^>]*>~i', ' ', $html) ?? $html;
  $text = strip_tags($html);
  $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
  return tts_audio_normalize_text($text);
}

function tts_audio_class_plan(PDO $pdo, int $classId, bool $allowDisabledClass = false): array {
  $stClass = $pdo->prepare(
    'SELECT id, school_year, period_label, grade_level, label, name, template_id,
            student_intro_html, student_intro_html_en, tts_enabled
     FROM classes WHERE id=? LIMIT 1'
  );
  $stClass->execute([$classId]);
  $class = $stClass->fetch(PDO::FETCH_ASSOC);
  if (!$class) throw new RuntimeException(t('tts_audio.error.class', 'Ungültige Klasse.'));
  if (!$allowDisabledClass && (int)($class['tts_enabled'] ?? 0) !== 1) throw new RuntimeException(t('tts_audio.error.disabled', 'Vorlesen ist für diese Klasse nicht aktiviert.'));

  $templateId = (int)($class['template_id'] ?? 0);
  $items = [];
  if ($templateId > 0) {
    $stFields = $pdo->prepare(
      "SELECT id, field_name, label, label_en, meta_json
       FROM template_fields
       WHERE template_id=? AND can_child_edit=1
       ORDER BY sort_order ASC, id ASC"
    );
    $stFields->execute([$templateId]);
    $groups = [];
    foreach ($stFields->fetchAll(PDO::FETCH_ASSOC) as $field) {
      foreach (['de', 'en'] as $language) {
        $de = trim((string)($field['label'] ?? ''));
        $en = trim((string)($field['label_en'] ?? ''));
        $text = $language === 'en' && $en !== '' ? $en : ($de !== '' ? $de : (string)$field['field_name']);
        tts_audio_plan_add($items, $text, $language, 'competency', 'field:' . (int)$field['id'] . ':' . $language, $text);
      }
      $meta = json_decode((string)($field['meta_json'] ?? ''), true);
      if (!is_array($meta)) $meta = [];
      $parts = app_group_parts_from_meta($meta);
      $groupKey = (string)$parts['group'];
      $subgroup = (string)$parts['subgroup'];
      if (!isset($groups[$groupKey])) $groups[$groupKey] = ['meta' => $meta, 'subgroups' => []];
      else $groups[$groupKey]['meta'] = $meta;
      if ($subgroup !== '') $groups[$groupKey]['subgroups'][$subgroup] = $meta;
    }
    $studentCfg = is_array(app_config()['student'] ?? null) ? app_config()['student'] : [];
    foreach ($groups as $groupKey => $groupData) {
      foreach (['de', 'en'] as $language) {
        $meta = is_array($groupData['meta'] ?? null) ? $groupData['meta'] : [];
        $mapKey = $language === 'en' ? 'group_titles_en' : 'group_titles';
        $titleMap = is_array($studentCfg[$mapKey] ?? null) ? $studentCfg[$mapKey] : [];
        $groupTitle = trim((string)($titleMap[$groupKey] ?? '')) ?: $groupKey;
        if ($language === 'en') {
          $metaTitle = app_group_meta_first_string($meta, ['group_title_en', 'category_en']);
          if ($metaTitle === '') $metaTitle = app_group_meta_rcff_first_string($meta, ['category_en']);
          if ($metaTitle !== '') $groupTitle = $metaTitle;
        }
        $prefix = tts_audio_translation($language, 'student.js.group_intro_tts', $language === 'en' ? 'Next up is the topic' : 'Weiter geht es mit dem Thema');
        $groupText = trim($prefix . ' ' . $groupTitle . '.');
        tts_audio_plan_add($items, $groupText, $language, 'section', 'group:' . $groupKey . ':' . $language, $groupText);
        foreach ((array)($groupData['subgroups'] ?? []) as $subgroup => $subMeta) {
          $subgroupTitle = (string)$subgroup;
          if ($language === 'en') {
            $translated = app_group_meta_first_string((array)$subMeta, ['subgroup_title_en', 'subcategory_en', 'subgroup_label_en']);
            if ($translated === '') $translated = app_group_meta_rcff_first_string((array)$subMeta, ['subcategory_en']);
            if ($translated !== '') $subgroupTitle = $translated;
          }
          $sectionTitle = $groupTitle . ' – ' . $subgroupTitle;
          $sectionText = trim($prefix . ' ' . $sectionTitle . '.');
          tts_audio_plan_add($items, $sectionText, $language, 'section', 'subgroup:' . $groupKey . ':' . $subgroup . ':' . $language, $sectionText);
        }
      }
    }
  }

  $stStudents = $pdo->prepare(
    'SELECT s.id, s.first_name, s.last_name
     FROM student_class_assignments sca
     INNER JOIN students s ON s.id=sca.student_id
     WHERE sca.class_id=? AND sca.is_active=1
     ORDER BY s.last_name, s.first_name, s.id'
  );
  $stStudents->execute([$classId]);
  $students = $stStudents->fetchAll(PDO::FETCH_ASSOC);
  $uploads = trim((string)(app_config()['app']['uploads_dir'] ?? 'uploads'), '/\\');
  foreach (['de', 'en'] as $language) {
    $introHtml = $language === 'en'
      ? trim((string)($class['student_intro_html_en'] ?? ''))
      : trim((string)($class['student_intro_html'] ?? ''));
    if ($introHtml === '' && $language === 'en') $introHtml = trim((string)($class['student_intro_html'] ?? ''));
    if ($introHtml === '') {
      $filename = $language === 'en' ? 'child_intro_en.html' : 'child_intro.html';
      $path = tts_audio_storage_project_root() . '/' . $uploads . '/' . $filename;
      if (!is_file($path) && $language === 'en') $path = tts_audio_storage_project_root() . '/' . $uploads . '/child_intro.html';
      if (is_file($path)) $introHtml = (string)file_get_contents($path);
    }
    if ($introHtml === '') continue;
    foreach ($students as $student) {
      $text = tts_audio_intro_text($introHtml, $class, $student);
      if ($text === '') continue;
      tts_audio_plan_add($items, $text, $language, 'intro', 'student:' . (int)$student['id'] . ':' . $language, $text);
    }
  }

  return array_values($items);
}

function tts_audio_storage_project_root(): string {
  return dirname(__DIR__);
}

function tts_audio_plan_add(
  array &$items,
  string $text,
  string $language,
  string $sourceType,
  string $sourceKey,
  string $sourceLabel
): void {
  $text = tts_audio_normalize_text($text);
  if ($text === '') return;
  $language = tts_audio_normalize_language($language);
  $voiceId = tts_audio_voice_for_language($language);
  $cacheKey = tts_audio_cache_key($text, $language, $voiceId);
  if (isset($items[$cacheKey])) return;
  $items[$cacheKey] = [
    'cache_key' => $cacheKey,
    'text' => $text,
    'language' => $language,
    'voice_id' => $voiceId,
    'source_type' => $sourceType,
    'source_key' => $sourceKey,
    'source_label' => $sourceLabel,
  ];
}

function tts_audio_reconcile_class_plan(PDO $pdo, int $classId, array $items): array {
  if ($classId <= 0 || !db_has_table($pdo, 'tts_audio_class_links') || !db_has_table($pdo, 'tts_audio_files')) {
    return ['links' => 0, 'files' => 0, 'bytes' => 0];
  }
  $requiredKeys = [];
  foreach ($items as $item) {
    $key = strtolower(trim((string)($item['cache_key'] ?? '')));
    if (preg_match('/^[a-f0-9]{64}$/', $key)) $requiredKeys[$key] = true;
  }

  $st = $pdo->prepare(
    "SELECT l.audio_id, f.cache_key
     FROM tts_audio_class_links l
     INNER JOIN tts_audio_files f ON f.id=l.audio_id
     WHERE l.class_id=? AND l.source_type IN ('competency','section','intro')"
  );
  $st->execute([$classId]);
  $staleAudioIds = [];
  foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $row) {
    $cacheKey = strtolower((string)($row['cache_key'] ?? ''));
    if (!isset($requiredKeys[$cacheKey])) $staleAudioIds[] = (int)$row['audio_id'];
  }
  $staleAudioIds = array_values(array_unique(array_filter($staleAudioIds)));
  if (!$staleAudioIds) return ['links' => 0, 'files' => 0, 'bytes' => 0];

  $placeholders = implode(',', array_fill(0, count($staleAudioIds), '?'));
  $params = array_merge([$classId], $staleAudioIds);
  $delete = $pdo->prepare(
    "DELETE FROM tts_audio_class_links
     WHERE class_id=? AND source_type IN ('competency','section','intro') AND audio_id IN ($placeholders)"
  );
  $delete->execute($params);
  $links = $delete->rowCount();
  $removed = tts_audio_remove_orphan_files($pdo, $staleAudioIds);
  return ['links' => $links, 'files' => $removed['files'], 'bytes' => $removed['bytes']];
}

function tts_audio_cleanup_class_plan(PDO $pdo, int $classId): array {
  $items = tts_audio_class_plan($pdo, $classId, true);
  return tts_audio_reconcile_class_plan($pdo, $classId, $items);
}

function tts_audio_cleanup_template_classes(PDO $pdo, int $templateId): array {
  if ($templateId <= 0) return ['classes' => 0, 'links' => 0, 'files' => 0, 'bytes' => 0];
  $st = $pdo->prepare('SELECT id FROM classes WHERE template_id=?');
  $st->execute([$templateId]);
  return tts_audio_cleanup_classes($pdo, array_map('intval', $st->fetchAll(PDO::FETCH_COLUMN)));
}

function tts_audio_cleanup_all_class_plans(PDO $pdo): array {
  $ids = $pdo->query(
    'SELECT DISTINCT c.id
     FROM classes c
     LEFT JOIN tts_audio_class_links l ON l.class_id=c.id
     WHERE c.tts_enabled=1 OR l.class_id IS NOT NULL'
  )->fetchAll(PDO::FETCH_COLUMN);
  return tts_audio_cleanup_classes($pdo, array_map('intval', $ids ?: []));
}

function tts_audio_cleanup_classes(PDO $pdo, array $classIds): array {
  $result = ['classes' => 0, 'links' => 0, 'files' => 0, 'bytes' => 0];
  foreach (array_values(array_unique(array_filter(array_map('intval', $classIds)))) as $classId) {
    try {
      $cleaned = tts_audio_cleanup_class_plan($pdo, $classId);
      $result['classes']++;
      $result['links'] += (int)$cleaned['links'];
      $result['files'] += (int)$cleaned['files'];
      $result['bytes'] += (int)$cleaned['bytes'];
    } catch (Throwable $e) {
      // Cleanup must never prevent saving the changed source text.
    }
  }
  return $result;
}

function tts_audio_remove_orphan_files(PDO $pdo, array $audioIds): array {
  $audioIds = array_values(array_unique(array_filter(array_map('intval', $audioIds), static fn(int $id): bool => $id > 0)));
  if (!$audioIds) return ['files' => 0, 'bytes' => 0];
  $removedFiles = 0;
  $removedBytes = 0;
  foreach ($audioIds as $audioId) {
    $st = $pdo->prepare(
      'SELECT f.id, f.storage_path, f.file_size
       FROM tts_audio_files f
       WHERE f.id=? AND NOT EXISTS (SELECT 1 FROM tts_audio_class_links l WHERE l.audio_id=f.id)
       LIMIT 1'
    );
    $st->execute([$audioId]);
    $row = $st->fetch(PDO::FETCH_ASSOC);
    if (!$row) continue;
    $pdo->prepare('DELETE FROM tts_audio_files WHERE id=?')->execute([$audioId]);
    $path = tts_audio_absolute_path((string)$row['storage_path']);
    if ($path !== null && is_file($path)) @unlink($path);
    $removedFiles++;
    $removedBytes += (int)($row['file_size'] ?? 0);
  }
  return ['files' => $removedFiles, 'bytes' => $removedBytes];
}

function tts_audio_delete_period(PDO $pdo, string $schoolYear, string $periodLabel): array {
  $schoolYear = trim($schoolYear);
  $periodLabel = normalize_class_period_label($periodLabel);
  if ($schoolYear === '') throw new RuntimeException(t('tts_audio.error.period', 'Schuljahr fehlt.'));
  $st = $pdo->prepare(
    'SELECT DISTINCT l.audio_id
     FROM tts_audio_class_links l
     INNER JOIN classes c ON c.id=l.class_id
     WHERE c.school_year=? AND c.period_label=?'
  );
  $st->execute([$schoolYear, $periodLabel]);
  $audioIds = array_map('intval', $st->fetchAll(PDO::FETCH_COLUMN));

  $pdo->beginTransaction();
  try {
    $del = $pdo->prepare(
      'DELETE l FROM tts_audio_class_links l
       INNER JOIN classes c ON c.id=l.class_id
       WHERE c.school_year=? AND c.period_label=?'
    );
    $del->execute([$schoolYear, $periodLabel]);
    $links = $del->rowCount();
    $pdo->commit();
    $removed = tts_audio_remove_orphan_files($pdo, $audioIds);
    return ['links' => $links, 'files' => $removed['files'], 'bytes' => $removed['bytes']];
  } catch (Throwable $e) {
    if ($pdo->inTransaction()) $pdo->rollBack();
    throw $e;
  }
}

function tts_audio_delete_file(PDO $pdo, int $audioId): array {
  if ($audioId <= 0) throw new RuntimeException(t('tts_audio.error.file', 'Ungültige Audiodatei.'));
  $st = $pdo->prepare('SELECT storage_path, file_size FROM tts_audio_files WHERE id=? LIMIT 1');
  $st->execute([$audioId]);
  $row = $st->fetch(PDO::FETCH_ASSOC);
  if (!$row) return ['files' => 0, 'bytes' => 0];
  $pdo->beginTransaction();
  try {
    $pdo->prepare('DELETE FROM tts_audio_class_links WHERE audio_id=?')->execute([$audioId]);
    $pdo->prepare('DELETE FROM tts_audio_files WHERE id=?')->execute([$audioId]);
    $pdo->commit();
  } catch (Throwable $e) {
    if ($pdo->inTransaction()) $pdo->rollBack();
    throw $e;
  }
  $path = tts_audio_absolute_path((string)$row['storage_path']);
  if ($path !== null && is_file($path)) @unlink($path);
  return ['files' => 1, 'bytes' => (int)($row['file_size'] ?? 0)];
}
